/* Kind-chat filter: blocks bad words, mean messages, threats, links and personal info. */
const LEET = { "0": "o", "1": "i", "3": "e", "4": "a", "5": "s", "7": "t", "8": "b", "@": "a", "$": "s", "!": "i", "|": "i", "+": "t", "€": "e", "£": "l", "v": "v" };
