function load() { try { const d = JSON.parse(fs.readFileSync(DATA_FILE, "utf8")); for (const a of d.accounts || []) { a.friends = a.friends || []; a.reqIn = a.reqIn || []; a.reqOut = a.reqOut || []; a.blocked = a.blocked || []; a.unread = a.unread || {}; accounts.set(a.uid, a); codeIdx.set(codeOf(a).toLowerCase(), a.uid); } for (const [k, v] of Object.entries(d.convos || {})) convos.set(k, v); console.log("Loaded " + accounts.size + " accounts"); } catch (e) { /* first run */ } }
