  if (d.t === "fa") { const b = accounts.get(String(d.uid)); if (!b || !a.reqIn.includes(b.uid)) return; link(a, b); dirty = true; pushState(a); pushState(b); const s = online.get(b.uid); if (s) send(s.ws, { t: "fok", why: a.name + " accepted your request!" }); return; }
