  if (d.t === "hist") { const b = accounts.get(String(d.uid)); if (!b || !a.friends.includes(b.uid)) return; const h = convos.get(ckey(a.uid, b.uid)) || []; a.unread[b.uid] = 0; dirty = true; send(me.ws, { t: "hist", uid: b.uid, msgs: h.slice(-40).map((m) => ({ me: m.f === a.uid, m: m.m, ts: m.ts })) }); pushState(a); return; }
