/* ---------- web + websocket ---------- */
const server = http.createServer((req, res) => {
  const url = (req.url || "/").split("?")[0];
  if (url === "/ww-ping") { res.writeHead(200, { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" }); res.end(JSON.stringify({ ww: 1, online: players.size, buddies: 1 })); return; }
  if (url === "/health") { res.writeHead(200); res.end("ok"); return; }
  if (url === "/" || url === "/index.html") { res.writeHead(200, { "Content-Type": "text/html; charset=utf-8", "Content-Encoding": "gzip", "Cache-Control": "no-cache" }); if (!GAME) GAME = Buffer.from(GAME_B64, "base64"); res.end(GAME); return; }
  res.writeHead(404); res.end("Not found");
});
var GAME = null;
const wss = new WebSocketServer({ server, path: "/ws", maxPayload: 4096 });
const players = new Map(); let nextId = 1; const ipCount = new Map();
