        if (a) { rename(a, me.name); me.acct = a; const old = online.get(a.uid); if (old && old !== me) { try { old.ws.close(); } catch (e) {} } online.set(a.uid, me); }
        send(ws, { t: "welcome", id: me.id, online: players.size, players: [...players.values()].filter(p => p !== me).map(p => ({ id: p.id, name: p.name, look: p.look })), acct: a ? { uid: a.uid, token: a.token, code: codeOf(a) } : null });
